import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Security — Offense Informed, Defense Minded","description":"Pentesting toolkit, XSS research, static analysis — finding holes before someone else does.","frontmatter":{"title":"Security — Offense Informed, Defense Minded","description":"Pentesting toolkit, XSS research, static analysis — finding holes before someone else does."},"headers":[],"relativePath":"en/skills/security/index.md","filePath":"en/skills/security/index.md"}`),a={name:`en/skills/security/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="security-—-offense-informed-defense-minded" tabindex="-1">Security — Offense Informed, Defense Minded <a class="header-anchor" href="#security-—-offense-informed-defense-minded" aria-label="Permalink to “Security — Offense Informed, Defense Minded”">​</a></h1><p>I learned security from the offensive side — building scanners, studying XSS, auditing source for unsafe patterns — because you cannot defend a system you cannot attack. That lens now runs over everything I ship, especially agent-written code.</p><h2 id="the-toolkit" tabindex="-1">The toolkit <a class="header-anchor" href="#the-toolkit" aria-label="Permalink to “The toolkit”">​</a></h2><ul><li><strong>Static analysis</strong> — my <a href="https://github.com/Godde3s/explorer" target="_blank" rel="noreferrer">explorer</a> project hunts vulnerable patterns and unsafe code paths in source trees.</li><li><strong>Web exploitation research</strong> — XSS flows, reverse-access patterns (<a href="https://github.com/Godde3s/access" target="_blank" rel="noreferrer">access</a>), bug-hunting utilities (<a href="https://github.com/Godde3s/thehunter" target="_blank" rel="noreferrer">thehunter</a>).</li><li><strong>Tooling literacy</strong> — the classic collection (<a href="https://github.com/Godde3s/Collection-" target="_blank" rel="noreferrer">Collection-</a>) every practitioner should know how to read.</li><li><strong>Hardening practice</strong> — token + 2FA admin panels, encrypted session vaults, minimum-surface deploys.</li></ul><h2 id="security-in-the-agentic-era" tabindex="-1">Security in the agentic era <a class="header-anchor" href="#security-in-the-agentic-era" aria-label="Permalink to “Security in the agentic era”">​</a></h2><p>Agents write more code than ever, and they write it <em>confidently</em> — including the insecure kind. My review checklist therefore treats every generated diff as untrusted input: injection surfaces, auth bypasses, secrets handling, dependency provenance. The <a href="/Usf/en/about/how-i-work/">method page</a> calls this the human review step; in security terms it is the only step that matters.</p><div class="warning custom-block"><p class="custom-block-title">Ethics clause</p><p>My offensive work targets systems I own or am authorized to test. Anything else is a crime, not a skill.</p></div>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};